#include <vector>
#include <set>
#include <tuple>

class Solution {
public:
    int numberOfSpacesCleaned(std::vector<std::vector<int>>& room) {
        int m = room.size(), n = room[0].size();
        int dirs[4][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        int r = 0, c = 0, d = 0;

        std::vector<std::vector<int>> visitedMask(m, std::vector<int>(n, 0));
        int cleanedCount = 0;

        while ((visitedMask[r][c] & (1 << d)) == 0) {
            if (visitedMask[r][c] == 0) cleanedCount++;
            visitedMask[r][c] |= (1 << d);

            int nr = r + dirs[d][0];
            int nc = c + dirs[d][1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && room[nr][nc] == 0) {
                r = nr;
                c = nc;
            } else {
                d = (d + 1) % 4;
            }
        }
        return cleanedCount;
    }
};

